import React from 'react';
import clsx from 'clsx';
import rangeParser from 'parse-numeric-range';
import {useThemeConfig, useColorMode} from '@docusaurus/theme-common';
import {useCodeWordWrap} from '@docusaurus/theme-common/internal';
import Highlight, {defaultProps, type Language} from 'prism-react-renderer';
import Line from '@theme/CodeBlock/Line';
import CopyButton from '@theme/CodeBlock/CopyButton';
import WordWrapButton from '@theme/CodeBlock/WordWrapButton';
import Container from '@theme/CodeBlock/Container';
import type {Props} from '@theme/CodeBlock/Content/String';

import styles from './styles.module.css';

const CODE_BLOCK_TITLE_REGEX = /title=(?<quote>["'])(?<title>.*?)\1/;
const METASTRING_LINES_RANGE_REGEX = /\{(?<range>[\d,-]+)\}/;

const COMMENT_PATTERNS = {
  js: {start: '\\/\\/', end: ''},
  jsBlock: {start: '\\/\\*', end: '\\*\\/'},
  jsx: {start: '\\{\\s*\\/\\*', end: '\\*\\/\\s*\\}'},
  bash: {start: '#', end: ''},
  html: {start: '<!--', end: '-->'},
  lua: {start: '--', end: ''},
  wasm: {start: '\\;\\;', end: ''},
  tex: {start: '%', end: ''},
} as const;

type CommentKind = keyof typeof COMMENT_PATTERNS;

const LANGUAGE_COMMENT_KINDS: {[language: string]: CommentKind[]} = {
  js: ['js', 'jsBlock'],
  javascript: ['js', 'jsBlock'],
  ts: ['js', 'jsBlock'],
  typescript: ['js', 'jsBlock'],
  jsx: ['js', 'jsBlock', 'jsx'],
  tsx: ['js', 'jsBlock', 'jsx'],
  html: ['js', 'jsBlock', 'html'],
  python: ['bash'],
  py: ['bash'],
  bash: ['bash'],
  markdown: ['html', 'jsx', 'bash'],
  md: ['html', 'jsx', 'bash'],
  tex: ['tex'],
  latex: ['tex'],
  matlab: ['tex'],
  lua: ['lua'],
  haskell: ['lua'],
  sql: ['lua'],
  wasm: ['wasm'],
};

const DEFAULT_COMMENT_KINDS = (
  Object.keys(COMMENT_PATTERNS) as CommentKind[]
).filter((pattern) => !['lua', 'wasm', 'tex'].includes(pattern));

export default function CodeBlockString({
  children,
  className: blockClassName = '',
  metastring,
  title: titleProp,
  showLineNumbers: showLineNumbersProp,
  language: languageProp,
}: Props): JSX.Element {
  const {
    prism: {defaultLanguage, magicComments, theme, darkTheme},
  } = useThemeConfig();
  const {colorMode} = useColorMode();
  const wordWrap = useCodeWordWrap();

  let prismTheme = theme;
  if (colorMode === 'dark') {
    if (darkTheme) {
      prismTheme = darkTheme;
    }
  }

  let language: string | undefined = languageProp;
  if (language == null) {
    const classTokens = blockClassName.split(' ');
    for (let i = 0; i < classTokens.length; i += 1) {
      const classToken = classTokens[i]!;
      if (classToken.startsWith('language-')) {
        language = classToken.replace(/language-/, '');
        break;
      }
    }
    if (language == null) {
      language = defaultLanguage;
    }
  }

  const title =
    metastring?.match(CODE_BLOCK_TITLE_REGEX)?.groups?.title || titleProp;

  let code = children.replace(/\n$/, '');
  const lineClassNames: {[lineIndex: number]: string[]} = {};
  const linesRange = metastring?.match(METASTRING_LINES_RANGE_REGEX)?.groups
    ?.range;

  if (linesRange) {
    if (magicComments.length === 0) {
      throw new Error(
        `A highlight range has been given in code block's metastring (\`\`\` ${metastring}), but no magic comment config is available. Docusaurus applies the first magic comment entry's className for metastring ranges.`,
      );
    }
    const metastringRangeClassName = magicComments[0]!.className;
    const highlightedLines = rangeParser(linesRange);
    for (let i = 0; i < highlightedLines.length; i += 1) {
      const n = highlightedLines[i]!;
      if (n > 0) {
        const lineIndex = n - 1;
        if (!lineClassNames[lineIndex]) {
          lineClassNames[lineIndex] = [];
        }
        lineClassNames[lineIndex]!.push(metastringRangeClassName);
      }
    }
  } else if (language !== undefined) {
    const commentKinds =
      LANGUAGE_COMMENT_KINDS[language] ?? DEFAULT_COMMENT_KINDS;
    const joinedDirectives = magicComments
      .flatMap((directive) => [
        directive.line,
        directive.block?.start,
        directive.block?.end,
      ])
      .filter((token): token is string => Boolean(token))
      .join('|');
    const commentPattern = commentKinds
      .map((kind) => {
        const pattern = COMMENT_PATTERNS[kind];
        return `(?:${pattern.start}\\s*(${joinedDirectives})\\s*${pattern.end})`;
      })
      .join('|');
    const directiveRegex = new RegExp(`^\\s*(?:${commentPattern})\\s*$`);
    const lines = code.split('\n');
    const blocks: {[className: string]: {start: number; range: string}} =
      Object.fromEntries(
        magicComments.map((directive) => [
          directive.className,
          {start: 0, range: ''},
        ]),
      );
    const lineToClassName: {[comment: string]: string} = Object.fromEntries(
      magicComments
        .filter((directive) => directive.line)
        .map((directive) => [directive.line!, directive.className]),
    );
    const blockStartToClassName: {[comment: string]: string} =
      Object.fromEntries(
        magicComments
          .filter((directive) => directive.block)
          .map((directive) => [directive.block!.start, directive.className]),
      );
    const blockEndToClassName: {[comment: string]: string} = Object.fromEntries(
      magicComments
        .filter((directive) => directive.block)
        .map((directive) => [directive.block!.end, directive.className]),
    );
    for (let lineNumber = 0; lineNumber < lines.length; ) {
      const line = lines[lineNumber]!;
      const match = line.match(directiveRegex);
      if (!match) {
        lineNumber += 1;
        continue;
      }
      const directive = match.find(
        (item, index) => index > 0 && item !== undefined,
      );
      if (directive) {
        if (lineToClassName[directive]) {
          const className = lineToClassName[directive]!;
          if (blocks[className]) {
            blocks[className]!.range += `${lineNumber},`;
          }
        } else if (blockStartToClassName[directive]) {
          const className = blockStartToClassName[directive]!;
          if (blocks[className]) {
            blocks[className]!.start = lineNumber;
          }
        } else if (blockEndToClassName[directive]) {
          const className = blockEndToClassName[directive]!;
          if (blocks[className]) {
            blocks[className]!.range += `${blocks[className]!.start}-${
              lineNumber - 1
            },`;
          }
        }
      }
      lines.splice(lineNumber, 1);
    }
    code = lines.join('\n');
    Object.entries(blocks).forEach(([className, block]) => {
      rangeParser(block.range).forEach((lineIndex) => {
        if (!lineClassNames[lineIndex]) {
          lineClassNames[lineIndex] = [];
        }
        lineClassNames[lineIndex]!.push(className);
      });
    });
  }

  let showLineNumbers = false;
  if (showLineNumbersProp == null) {
    if (metastring) {
      showLineNumbers = metastring.includes('showLineNumbers');
    }
  } else {
    showLineNumbers = showLineNumbersProp;
  }

  return (
    <Container
      as="div"
      className={clsx(
        blockClassName,
        language &&
          !blockClassName.includes(`language-${language}`) &&
          `language-${language}`,
      )}>
      {title ? <div className={styles.codeBlockTitle}>{title}</div> : null}
      <div className={styles.codeBlockContent}>
        <Highlight
          {...defaultProps}
          theme={prismTheme}
          code={code}
          language={(language ?? 'text') as Language}>
          {({className, tokens, getLineProps, getTokenProps}) => (
            <pre
              /* eslint-disable-next-line jsx-a11y/no-noninteractive-tabindex */
              tabIndex={0}
              ref={wordWrap.codeBlockRef}
              className={clsx(className, styles.codeBlock, 'thin-scrollbar')}>
              <code
                className={clsx(
                  styles.codeBlockLines,
                  showLineNumbers
                    ? styles.codeBlockLinesWithNumbering
                    : undefined,
                )}>
                {tokens.map((line, i) => {
                  if (line.length === 1) {
                    if (line[0]) {
                      if (line[0].content === '\n') {
                        line[0].content = '';
                      }
                    }
                  }
                  return (
                    <Line
                      key={i}
                      line={line}
                      getLineProps={getLineProps}
                      getTokenProps={getTokenProps}
                      classNames={lineClassNames[i]}
                      showLineNumbers={showLineNumbers}
                    />
                  );
                })}
              </code>
            </pre>
          )}
        </Highlight>
        <div className={styles.buttonGroup}>
          {wordWrap.isEnabled || wordWrap.isCodeScrollable ? (
            <WordWrapButton
              className={styles.codeButton}
              onClick={() => wordWrap.toggle()}
              isEnabled={wordWrap.isEnabled}
            />
          ) : null}
          <CopyButton className={styles.codeButton} code={code} />
        </div>
      </div>
    </Container>
  );
}
